using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Suppliers;
[Authorize]public sealed class EditModel(MediStockDbContext db):PageModel{[BindProperty(SupportsGet=true)]public int Id{get;set;}[BindProperty]public SupplierInput Input{get;set;}=new();public async Task<IActionResult>OnGetAsync(CancellationToken ct){var x=await db.Suppliers.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==Id,ct);if(x is null)return NotFound();Input=new SupplierInput{Name=x.Name,ContactPerson=x.ContactPerson,Phone=x.Phone,Email=x.Email,Address=x.Address};return Page();}public async Task<IActionResult>OnPostAsync(CancellationToken ct){var x=await db.Suppliers.SingleOrDefaultAsync(x=>x.Id==Id,ct);if(x is null)return NotFound();if(!ModelState.IsValid)return Page();x.Name=Input.Name.Trim();x.ContactPerson=Clean(Input.ContactPerson);x.Phone=Input.Phone.Trim();x.Email=Clean(Input.Email);x.Address=Clean(Input.Address);await db.SaveChangesAsync(ct);TempData["StatusMessage"]="Supplier changes saved.";return RedirectToPage("Details",new{id=Id});}private static string?Clean(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();}
